import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"裸机云监控功能说明","description":"","frontmatter":{"title":"裸机云监控功能说明"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/monitoring-guide.md","filePath":"ops-knowledge-base/baremetal/monitoring-guide.md","lastUpdated":1788259091000}'),r={name:"ops-knowledge-base/baremetal/monitoring-guide.md"};function o(h,a,d,p,n,s){return t(),i("div",null,[...a[0]||(a[0]=[e('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍裸机云控制台监控功能的使用方法，包括监控指标说明、历史数据查看及常见问题，帮助您实时了解服务器资源使用情况，便于日常运维及故障排查。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、监控功能介绍" tabindex="-1">一、监控功能介绍 <a class="header-anchor" href="#一、监控功能介绍" aria-label="Permalink to &quot;一、监控功能介绍&quot;">​</a></h2><p>裸机云控制台提供服务器运行监控功能，可查看服务器各项资源的使用情况及历史趋势。</p><p>通过监控页面，您可以快速了解服务器当前运行状态，并结合历史数据分析资源使用情况，为服务器运维及性能优化提供参考。</p><p>目前支持查看以下监控指标：</p><ul><li>CPU 使用率</li><li>内存用量</li><li>硬盘 I/O</li><li>网卡流量</li><li>用量统计图</li></ul><p>同时支持按日期及时间范围查看历史监控数据。</p><hr><h2 id="二、如何查看监控信息" tabindex="-1">二、如何查看监控信息 <a class="header-anchor" href="#二、如何查看监控信息" aria-label="Permalink to &quot;二、如何查看监控信息&quot;">​</a></h2><ol><li>登录 <strong>Raksmart 客户后台</strong>。</li><li>进入 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>选择需要查看的服务器。</li><li>点击进入 <strong>管理</strong> 页面。</li><li>点击 <strong>监控</strong>。</li></ol><p>进入监控页面后，即可查看服务器各项资源使用情况。</p><hr><h2 id="三、监控指标说明" tabindex="-1">三、监控指标说明 <a class="header-anchor" href="#三、监控指标说明" aria-label="Permalink to &quot;三、监控指标说明&quot;">​</a></h2><h2 id="cpu-使用率" tabindex="-1">CPU 使用率 <a class="header-anchor" href="#cpu-使用率" aria-label="Permalink to &quot;CPU 使用率&quot;">​</a></h2><p>CPU 使用率用于反映服务器处理器资源的使用情况。</p><p>CPU 长时间处于较高使用率时，可能表示：</p><ul><li>服务器业务负载较高；</li><li>应用程序占用较多 CPU 资源；</li><li>存在异常进程或任务。</li></ul><hr><h2 id="内存用量" tabindex="-1">内存用量 <a class="header-anchor" href="#内存用量" aria-label="Permalink to &quot;内存用量&quot;">​</a></h2><p>内存用量用于显示服务器当前内存资源的占用情况。</p><p>当内存长期接近满载时，可能导致：</p><ul><li>系统运行缓慢；</li><li>应用程序响应变慢；</li><li>服务运行异常。</li></ul><p>建议及时检查内存占用情况，并根据业务需求进行优化或升级配置。</p><hr><h2 id="硬盘-i-o" tabindex="-1">硬盘 I/O <a class="header-anchor" href="#硬盘-i-o" aria-label="Permalink to &quot;硬盘 I/O&quot;">​</a></h2><p>硬盘 I/O 用于反映服务器磁盘读写情况。</p><p>当磁盘 I/O 长时间较高时，可能表示：</p><ul><li>大量文件读写；</li><li>数据库访问频繁；</li><li>数据备份或同步任务运行；</li><li>磁盘读写压力较大。</li></ul><hr><h2 id="网卡流量" tabindex="-1">网卡流量 <a class="header-anchor" href="#网卡流量" aria-label="Permalink to &quot;网卡流量&quot;">​</a></h2><p>网卡流量用于显示服务器网络数据传输情况。</p><p>可用于观察：</p><ul><li>网络流量变化趋势；</li><li>业务访问情况；</li><li>上传、下载流量变化。</li></ul><p>如网络流量短时间内明显增加，建议结合业务情况进一步分析是否属于正常访问。</p><hr><h2 id="用量统计图" tabindex="-1">用量统计图 <a class="header-anchor" href="#用量统计图" aria-label="Permalink to &quot;用量统计图&quot;">​</a></h2><p>监控页面提供资源使用趋势图，可直观查看服务器各项资源在不同时间段内的变化情况。</p><p>支持根据需要选择不同的日期及时间范围，查看历史监控数据，便于分析资源使用趋势及定位异常发生时间。</p><hr><h2 id="四、如何判断服务器是否存在异常" tabindex="-1">四、如何判断服务器是否存在异常 <a class="header-anchor" href="#四、如何判断服务器是否存在异常" aria-label="Permalink to &quot;四、如何判断服务器是否存在异常&quot;">​</a></h2><p>监控数据可帮助您快速判断服务器是否存在资源异常。</p><p>常见情况如下：</p><blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>监控现象</td><td>可能原因</td></tr><tr><td>CPU 长时间保持较高使用率</td><td>业务负载较高、程序占用资源较多或存在异常进程</td></tr><tr><td>内存持续接近满载</td><td>内存资源不足、应用程序占用较高或存在内存泄漏</td></tr><tr><td>硬盘 I/O 长时间较高</td><td>大量磁盘读写、数据库操作频繁或备份任务运行</td></tr><tr><td>网卡流量突然增加</td><td>业务访问增长、文件传输、数据同步或异常网络访问</td></tr><tr><td>某项资源持续高于平时水平</td><td>建议结合系统日志及业务运行情况进一步排查</td></tr></tbody></table><p><strong>说明：</strong></p><p>监控数据仅用于反映服务器资源使用情况，具体原因仍需结合系统日志、业务运行状态及服务器配置综合分析。</p></blockquote><hr><h2 id="五、查看历史监控数据" tabindex="-1">五、查看历史监控数据 <a class="header-anchor" href="#五、查看历史监控数据" aria-label="Permalink to &quot;五、查看历史监控数据&quot;">​</a></h2><p>监控页面支持查看历史资源使用情况。</p><p>您可以根据需要选择对应的日期及时间范围，查看服务器在指定时间内的资源使用趋势。</p><p>历史监控数据可用于：</p><ul><li>分析服务器性能变化；</li><li>排查业务异常发生时间；</li><li>对比资源使用趋势；</li><li>辅助定位性能问题。</li></ul><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="q1-监控数据是实时更新的吗" tabindex="-1">Q1：监控数据是实时更新的吗？ <a class="header-anchor" href="#q1-监控数据是实时更新的吗" aria-label="Permalink to &quot;Q1：监控数据是实时更新的吗？&quot;">​</a></h3><p>监控数据会按照系统采集周期进行更新，因此页面显示的数据可能存在短时间延迟。</p><hr><h3 id="q2-cpu-使用率很高-是服务器故障吗" tabindex="-1">Q2：CPU 使用率很高，是服务器故障吗？ <a class="header-anchor" href="#q2-cpu-使用率很高-是服务器故障吗" aria-label="Permalink to &quot;Q2：CPU 使用率很高，是服务器故障吗？&quot;">​</a></h3><p>不一定。</p><p>CPU 使用率较高通常表示服务器正在处理较多任务，也可能是业务访问增加、程序运行或系统任务导致。</p><p>建议结合业务运行情况进一步分析。</p><hr><h3 id="q3-为什么网络流量突然增加" tabindex="-1">Q3：为什么网络流量突然增加？ <a class="header-anchor" href="#q3-为什么网络流量突然增加" aria-label="Permalink to &quot;Q3：为什么网络流量突然增加？&quot;">​</a></h3><p>网络流量增加可能由以下原因造成：</p><ul><li>网站访问量增加；</li><li>文件上传或下载；</li><li>数据同步；</li><li>程序更新；</li><li>异常网络访问。</li></ul><p>建议结合服务器日志及业务情况进行判断。</p><hr><h3 id="q4-监控正常-但服务器无法访问怎么办" tabindex="-1">Q4：监控正常，但服务器无法访问怎么办？ <a class="header-anchor" href="#q4-监控正常-但服务器无法访问怎么办" aria-label="Permalink to &quot;Q4：监控正常，但服务器无法访问怎么办？&quot;">​</a></h3><p>监控数据显示正常并不代表服务器所有服务均正常运行。</p><p>建议进一步检查：</p><ul><li>网络连接状态；</li><li>安全组配置；</li><li>系统防火墙；</li><li>SSH 或远程桌面（RDP）服务；</li><li>应用程序运行状态。</li></ul><p>如仍无法确认原因，可通过 VNC 或 Rescue（救援系统）进一步排查。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 监控数据主要用于观察服务器资源使用情况，不作为业务性能的唯一判断依据。</p><p>⚠️ 建议定期查看 CPU、内存、硬盘 I/O 及网卡流量变化，及时发现资源异常。</p><p>⚠️ 支持按日期及时间范围查看历史监控数据，便于分析资源使用趋势及故障发生时间。</p><p>⚠️ 如发现资源长期处于高负载状态，建议优化应用程序或升级服务器配置。</p><hr>',79)])])}const b=l(r,[["render",o]]);export{c as __pageData,b as default};
